  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    node_map = {node['id']: node for node in nodes}
    children = {}
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children.setdefault(parent, []).append(node['id'])
    all_symbols = {node['symbol'] for node in nodes}
    missing = required_symbols - all_symbols
    if missing:
        raise ValueError(f"Required symbols missing: {missing}")
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    retained = {node['id'] for node in nodes}
    sym_count = {}
    for node in nodes:
        sym_count[node['symbol']] = sym_count.get(node['symbol'], 0) + 1
    removed = []
    for node in sorted_nodes:
        nid = node['id']
        if not node['removable'] or node['parent'] is None:
            continue
        child_ids = children.get(nid, [])
        has_retained_child = any(cid in retained for cid in child_ids)
        if has_retained_child:
            continue
        sym = node['symbol']
        new_count = sym_count[sym] - 1
        if sym in required_symbols and new_count < 1:
            continue
        removed.append(nid)
        retained.remove(nid)
        sym_count[sym] = new_count
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }"
}
